def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    # Find connected components of colored cells, excluding the 5 scaffold.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if src[r][c] in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            src[ny][nx] not in (0, 5) and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(cells)

    # Repeat the colored pattern beside each vertical 5-line.
    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5:
                r += 1
                continue
            lo = r
            while r < h and src[r][c] == 5:
                r += 1
            hi = r - 1
            if hi == lo:
                continue

            for side in (c - 1, c + 1):
                if not (0 <= side < w):
                    continue
                comp = next((cells for cells in components if any(
                    x == side and lo <= y <= hi for y, x in cells
                )), None)
                if comp is None:
                    continue
                r0 = min(y for y, x in comp)
                r1 = max(y for y, x in comp)
                c0 = min(x for y, x in comp)
                c1 = max(x for y, x in comp)
                ph = r1 - r0 + 1
                for y in range(lo, hi + 1):
                    sy = r0 + (y - r0) % ph
                    for x in range(c0, c1 + 1):
                        out[y][x] = src[sy][x]

    # Repeat the colored pattern beside each horizontal 5-line.
    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5:
                c += 1
                continue
            lo = c
            while c < w and src[r][c] == 5:
                c += 1
            hi = c - 1
            if hi == lo:
                continue

            for side in (r - 1, r + 1):
                if not (0 <= side < h):
                    continue
                comp = next((cells for cells in components if any(
                    y == side and lo <= x <= hi for y, x in cells
                )), None)
                if comp is None:
                    continue
                r0 = min(y for y, x in comp)
                r1 = max(y for y, x in comp)
                c0 = min(x for y, x in comp)
                c1 = max(x for y, x in comp)
                pw = c1 - c0 + 1
                for x in range(lo, hi + 1):
                    sx = c0 + (x - c0) % pw
                    for y in range(r0, r1 + 1):
                        out[y][x] = src[y][sx]

    return out
